[
  {
    "type": "function",
    "function": {
      "name": "web_search",
      "description": "检索公开网页，查找模型还不知道的当前信息、新闻或报告。",
      "parameters": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "检索关键词"
          }
        },
        "required": [
          "query"
        ]
      }
