        "type": "object",
        "properties": {
          "target_language": {
            "type": "string",
            "description": "要译成的语言，例如英语、德语、中文"
          },
          "text": {
            "type": "string",
            "description": "要翻译的原话，当这些话就在这条用户消息里时填写"
