def analyze(datasets):
    contract = None
    for ds in datasets:
        if 'annual_sales_target' in ds.get('columns', []):
            contract = ds['rows'][0]
            break
    if not contract:
        return []
    target = contract['annual_sales_target']['amount']
    currency = contract['annual_sales_target_currency']
    start = contract['term_start_date']
    end = contract['term_end_date']
    confirmed = 0.0
    for ds in datasets:
