            for row in ds['rows']:
                if row['month'] >= '2026-10':
                    confirmed += float(row['total_amount'])
    completion = confirmed / target * 100 if target else 0
    return [
        {'title': '年度销售目标', 'detail': f'合同年度目标为 {target:,.0f} {currency}，期限 {start} 至 {end}。', 'evidence': {'target': target, 'currency': currency, 'term_start': start, 'term_end': end}},
